    TOWER_DWARF_4_INCENDIARY_AMMO_3_NAME = "Đạn cháy",
    LEVEL_115_HISTORY = "“Chúng tôi đã thành công ra khỏi thung lũng, và bây giờ chỉ có một cái chặn giữa chúng tôi và mắt ma quỷ, chỉ còn lại là Mydrias. Từ lâu chúng ta đã thấy được khả năng của cô ấy ở thung lũng, nhưng ở đây, cô ấy có sự quan sát và sự bảo vệ của chủ nhân, chắc chắn sẽ chiếm được lợi thế lớn hơn. Tuy nhiên, chúng ta vẫn không bị chặn bởi sự bất ổn. Tăng lên!",
	LEVEL_104_HISTORY = "Hiện tại, trái tim của rừng đã an toàn, chúng ta phải tái hợp, chiến thắng theo đuổi. Đã đến lúc đưa mặt trận đến vùng đất của động vật. Lấy quân vào các cột cây, tìm kiếm các trại từ các điểm cao.",
	LEVEL_107_HISTORY = "Sau khi ngăn cản các loài động vật phá hoại rừng, chúng tôi theo dõi những người khủng khiếp đang đẩy lùi, đến một vùng đất hoang dã. Đây là điểm mà chúng ta nghi ngờ là những kế hoạch ác. Địch trong bóng tối, tôi hiểu, phải cẩn thận. họ dường như có một số điều không rõ ràng.",
	LEVEL_105_HISTORY = "Nhờ bạn chiếm được những điểm cao, chúng tôi đã tìm thấy một trại của những con thú trong một khu vực cổ ngoài rừng. Hãy hướng dẫn quân đội tới lãnh thổ của họ, đồng thời cảnh giác về sự chìm nát của họ. Mặc dù chúng tôi đã giành chiến thắng một trận chiến nữa, nhưng nó vẫn chưa kết thúc.",
	LEVEL_130_HISTORY = "Cuối cùng, chúng tôi đã đến với cái hầm của nữ thần trong miệng họ – một ngôi đền bị phá hủy, bị bỏ rơi từ lâu, và dưới sự áp lực của lịch sử bị đóng băng đã bị sụp đổ. Thượng Đế đã bỏ rơi thế giới này, thật sự xứng đáng với ngai vàng như vậy. Phải chặn hoàn toàn những loài côn trùng này, không còn một.",
	LEVEL_126_HISTORY = "Tôi đi qua một cái núi lớn và đi qua một căn phòng đầy những chiếc xe lớn, những thứ trong xe này không thể nào. Không có gì ngạc nhiên khi những người lười biếng này đầy sức mạnh, kỹ năng và hình dạng cũng như một mô-đun được vẽ ra. Tất cả đều là những người lười biếng - những người lừa đảo! Ông sử dụng các nguồn khoa học ác để tạo ra các bản sao của mình. - Thưa ông, chúng ta phải ngăn chặn mọi chuyện!",
	LEVEL_119_HISTORY = "Eridan đã chiến đấu đến nỗi đã mệt mỏi, ông hướng dẫn chúng ta đến đền thờ bị rơi, một thợ săn tên là Thống đốc linh hồn Navira đã thức dậy các lực lượng sống để cố gắng dẫn dắt họ trên lục địa. Tôi phải ngăn chặn anh ta với mọi giá!",
	LEVEL_123_HISTORY = "Các nhà điều tra cho biết, các ngọn núi gần đó đã bị sụp đổ bất thường. Các cuộc điều tra khác cho thấy các nghi phạm là một nhóm người lười biếng đang lắp ráp một chiếc máy bay khổng lồ ở phía nam của núi. - Thưa ông, xin hãy đi điều tra.",
	LEVEL_114_HISTORY = "Các sinh vật xấu xí này không biết từ đâu đến! Các lực lượng lớn đã mệt mỏi, mọi thứ chúng ta chạm vào đều như thể có sự sống, sẵn sàng tấn công chúng ta bất cứ lúc nào, dường như toàn bộ đất nước đang làm hết sức mình để đối đầu với chúng ta. Phải chăng tiên tri Ma-thi-a và răng của ông sẽ ở gần đó.",
	LEVEL_116_HISTORY = "Mydrias không còn tồn tại nữa, nhưng đôi mắt ma quỷ của kẻ địch mạnh mẽ hơn vẫn đang chờ chúng ta. Đây là cơ hội cuối cùng để chấm dứt toàn bộ giáo phận và xâm lược. Nếu chúng ta không thể đoàn kết đến phút cuối cùng, sau đó, bất kể mọi sự diễn ra như thế nào, sẽ không có ý nghĩa gì. Bắt đầu chiến đấu! Chỉ có chế độ chiến đấu, chế độ chiến tranh có thể thu được thêm 2 ngôi sao.",
	LEVEL_127_HISTORY = "Sự kết hợp của các lực lượng thép tối trong núi này đã được chúng ta chặn gần như thành công, nhưng nếu những lời khuyên vẫn còn ngoài luật pháp, mọi thứ sẽ được đưa vào dòng đông. Anh ấy chắc chắn đang hoàn thành công việc cuối cùng, sẵn sàng để khởi động đầu của máy tính. Chúc các bạn có thể leo lên đỉnh núi, nhưng lần này chúng ta sẽ phải đối mặt với những câu đố thực sự.",
	LEVEL_106_HISTORY = "Có lẽ chúng ta đã nắm lấy gió trong cuộc chiến chống lại động vật, nhưng chúng ta vẫn phải đối mặt với những người lãnh đạo của chúng. Vua của thú cưng này là một đối thủ mạnh mẽ, vì vậy đừng bị lừa dối bởi sự ngu ngốc của mình, nếu không bạn sẽ chết dưới răng của nó.",
	LEVEL_120_HISTORY = "“Chúng tôi đã nhận được sự cứu trợ khẩn cấp từ các loài cây ở biên giới rừng, chúng đang bị tấn công vô tình bởi các loài crocodile, chúng không thể chịu được bao lâu nữa. Hãy cẩn thận, tướng. Có rất nhiều bí ẩn trong bụng của những con crocodile.",
	LEVEL_122_HISTORY = "Sau khi đến nhà thờ cổ, những điều quan tâm nhất vẫn xảy ra. Từ lâu bảo vệ thế giới không bị xâm phạm, đảng phái “người ăn thịt, ăn thịt” gần như bị hủy hoại, chỉ còn vài người trong số các linh hồn của cây Samantha đang cố gắng duy trì. tướng, ngăn chặn sự sụp đổ của đất đai, nếu không cả vương quốc sẽ rơi vào miệng lớn của ông không bao giờ hài lòng.",
	LEVEL_108_HISTORY = "Khi chúng ta đi sâu vào lãnh thổ giáo xứ, chúng ta đã tìm thấy một loạt các hang động khổng lồ, đầy những tinh thể phản ánh với phép thuật kỳ lạ. Nhà thờ Phục sinh đang khai thác các tinh thể này, mà không có nghi ngờ là để phục vụ như một nguồn năng lượng. Mục đích là gì, chúng tôi vẫn chưa biết, nhưng sự can thiệp của hoạt động khai thác chắc chắn có thể làm hỏng chân của họ một cách hiệu quả.",
	LEVEL_121_HISTORY = "Nơi làng đã an toàn, người dân Trái Đất nói với chúng ta rằng trước khi cuộc tấn công xảy ra, họ cảm thấy dấu vết cổ xưa đã bị sụp đổ, đó có lẽ là lý do cho cuộc tấn công đột ngột của người dân Crocodile. Với dấu vết này, chúng tôi đi sâu vào trung tâm của hồ, và ngẫu nhiên phát hiện ra một cây đá cổ, nó trông giống như một cái nho. một cái nô lệ của một sinh vật khổng lồ.",
	LEVEL_102_HISTORY = "Hãy cẩn thận, thông tin đã được truyền qua Sanhedrin! Hầm rừng bị tấn công! Ta phải trở lại để giúp đỡ cây. Một số lực lượng của quân đội tối sẽ tham gia chiến trường với chúng tôi, để giữ cảnh giác trong thời gian này. Hiện tại chúng ta có thể cùng nhau làm việc, nhưng mọi thứ có thể thay đổi bất cứ lúc nào.",
	LEVEL_124_HISTORY = "Mặc dù con rùa luôn nổi tiếng với những phát minh của mình, nhưng bộ tộc này gọi mình là \"cây thép tối\" đã bị đốt vào ma quỷ, thậm chí để cho con rùa của người Boguel nhìn thấy nhau, một lò sau đó một lò không ngừng làm thép vũ trang mình. Ai là người đằng sau cái này? chúng ta phải tìm ra sự thật!",
	LEVEL_125_HISTORY = "Như chúng ta lo lắng, chỉ có bên trong núi này mới có thể chứa đủ để tạo ra một chiếc lò nướng lớn như vậy. Có bao nhiêu con khỉ ở đây? Rất nhiều người ngăn cản chúng ta tiến lên, nhưng vẫn còn những người liên tục cạo râu và trượt. Thật lạ, họ đều giống nhau? Có lẽ trong đó có một bí mật không thể tiết lộ.",
	LEVEL_117_HISTORY = "Cây rừng kỳ lạ của thời cổ đã đầy hơi thở vô tình và khủng khiếp. Có tin rằng các chiến binh linh hồn và linh hồn đang lặn đất này, tấn công hành khách, phá hoại rừng. - Thưa ông, chúng ta phải tiến hành điều tra sâu sắc.",
	LEVEL_101_HISTORY = "“Chúng tôi đã tìm kiếm trong rừng phía nam trong nhiều tháng, nhưng không thể tìm thấy dấu vết của vua Denas. Và trong thời gian này, chúng ta đã kết hợp với các linh hồn của thiên nhiên – linh hồn cây để làm bạn bè và gặp gỡ những người láng giềng của họ – những người lười biếng, họ đã tiếp tục tấn công chúng ta khi họ gặp chúng ta.\n“Chúng ta phải kết thúc cuộc chiến này càng sớm càng tốt để tiếp tục tìm kiếm vua.",
	LEVEL_129_HISTORY = "Càng sâu đi, chúng ta càng có thể cảm nhận rõ ràng rằng nỗi sợ hãi đã ở trong bóng tối trong một thời gian dài, chỉ chờ đợi thời gian trưởng thành để tiến hành cuộc tấn công. Mạng lưới xung quanh này, bóng tối kỳ lạ lùng, tôi dám nói chúng ta không xa cốt lõi của hang.",
	LEVEL_111_HISTORY = "Cuối cùng chúng tôi đã rời khỏi Canyon, nhưng đường đi vẫn còn dài. Bây giờ chúng ta đứng trước một cửa truyền thông khổng lồ đầy tinh thể, nhìn thấy tiên tri Mydrias đã hoàn thành lễ hội của cô. Tôi không biết sẽ xảy ra điều gì, nhưng tôi vẫn đang chờ đợi. Tất cả cảnh giác!",
	LEVEL_118_HISTORY = "Các nhà báo tin rằng các linh hồn sẽ không thể chống lại cuộc tấn công của quân đội sống. “Chúng ta phải nhanh chóng đi hỗ trợ các lực lượng thần linh và đội trưởng của họ – Eridan – để không còn quá muộn nữa. Sau khi giữ lại đài, chúng ta có thể tiếp tục tiến tới nguồn gốc của cuộc xâm lược này.",
	LEVEL_109_HISTORY = "Các đường mòn này bị xoay quanh, nhưng chúng tôi chắc chắn đã đi đúng hướng, vì hoạt động của Hội thánh Đế ngày càng tăng. Khi chúng ta dần dần sâu, những cảnh khủng khiếp khác nhau xuất hiện trong các bức tường, điều này không thể khiến người ta nghi ngờ mức độ khủng khiêu trong giáo phận là bao nhiêu.",
	LEVEL_103_HISTORY = "Tôi đã trở về trong rừng, nhưng con thú đã phá vỡ đường phòng thủ. Đánh bại tâm hồn, tăng cường vị trí! Nếu không bảo vệ trái tim của rừng, thì rừng và các loài cây sẽ bị hủy diệt.",
	LEVEL_110_HISTORY = "Nhà thờ hồi sinh sử dụng tinh thể khai thác, xây dựng một thiết bị ngoại hình kỳ lạ bên ngoài Canyon. Nó có tiếng ồn, đầy năng lượng kỳ lạ, ngay cả không khí xung quanh cũng có vẻ nặng. Không thể bỏ qua điều này trước khi chúng ta tiếp tục sâu sắc.",
	LEVEL_113_HISTORY = "Các ngôi đền nổi tiếng của đám mây mờ xuất hiện trên chân trời. Đi theo hướng rất rõ ràng, theo những mùi hôi và sự khác biệt ngày càng mạnh mẽ, chúng ta sẽ tìm ra nguồn gốc của tất cả những điều này. Tất cả những gì chúng ta cần làm là sống sót trong đất quái vật đang nổi lên.",
	LEVEL_112_HISTORY = "Tôi đã gặp lại Vua Denas và cùng nhau đi qua cổng truyền thông vào thế giới không rõ. Thế giới kỳ lạ này trông giống như một cái bóng lỏng lỏng của Linirea, nhưng nó đầy rắc rối. Hãy cẩn thận, những gì nằm trong bóng tối có thể còn khủng khiếp hơn là một nhà thờ hồi sinh.",
	LEVEL_128_HISTORY = "Sau những dấu hiệu của các nhà điều tra, chúng tôi tìm thấy dấu vết của những người theo đạo đức không thể tách rời. Họ dường như đang tìm kiếm một vị thần mới để cầu nguyện – một quái vật ác, mờ mịt. những người theo đạo và những con rắn? Cả hai đều có một cái gì đó tốt!",
	LEVEL_131_HISTORY = "Sau chiến tranh, vương quốc trở lại hòa bình. Giờ đây, chỉ cần lắng nghe sóng bắn biển, đặt một vòng tròn, chờ đợi một người bạn cũ. Tuy nhiên, ngay cả khi có một cái gió yên tĩnh, tôi chỉ sợ ngày bình yên này không nhiều.",
	LEVEL_132_HISTORY = "Lúc đó, chúng tôi đã đi theo núi lửa, và thấy một ngôi đền hoang dã, nơi đây là nơi phục vụ lửa.\n\nTuy nhiên, người dân tỉnh tỉnh thẳm thẳm lúa đỏ, đã không tranh cãi với thế giới, nhưng bây giờ vẫn lo lắng, thở phào. Chắc chắn là cái này là cái đỏ của con cái.",
	LEVEL_133_HISTORY = "Sau trận chiến đỏ, quân đội của chúng tôi tiến lên phía trước, thẳng đến đảo gió. Khi lên bờ, cơn bão bắt đầu, xoay như một con rắn. Đảo này rất nguy hiểm, nhưng đó là con đường cần thiết đến đền hoàng tử Iron Fan! Hãy cẩn thận, cơn bão sẽ đến!",
	LEVEL_134_HISTORY = "Lúc trước, tất cả những gì công chúa đã ban cho. Đội ngũ của chúng tôi phá hủy bão, đến nơi gió. Ở đây tòa nhà an toàn, cảnh đẹp nhưng ẩn máy giết người, đừng rời đi! Dù là nhà của vua quỷ, cũng có thể ngăn cản quân đội của chúng ta đi trước!",
	LEVEL_135_HISTORY = "Chiến tranh tại! Vua Sư tử sống trên thành vàng, quân đội còn lại, quyết định với sức mạnh khôn ngoan, mặt đối đầu phá thù! Phải cắt rễ trước khi anh ta nhảy múa.\nVì núi xã hội, vì trời dưới trời sinh - Liên đoàn tướng, xếp hạng!",
	LEVEL_136_TITLE = "Dragon's Gate",
	LEVEL_136_HISTORY = "Các nhà khám phá thiên đường mang lại tin tức đáng lo ngại: trên bầu trời xa xôi của Vương quốc, họ phát hiện ra một cái cột bụi đã lâu dài, được viết bằng các văn bản cổ điển, một cổng truyền điệu bí ẩn.\nMặc dù những lời nói cổ đại đã đưa ra lời cảnh báo mạnh mẽ: “Không nên bước vào đất nước của đám mây”, vua và Vez'nan vẫn quyết định đi tìm sự thật. //Điều này là phiên bản cũ 36, cho hai xuất khẩu, phiên bản mới 36 đóng sau khi hoàn thành dòng này.",
	LEVEL_137_TITLE = "Warden Fortress",
	LEVEL_137_HISTORY = "Đã qua cửa truyền, chúng ta bước vào đất nước của đám mây. Nhiệm vụ của chuyến đi này đã rõ ràng: giúp Ollion bảo vệ \"người thợ mỏ cuối cùng\". Vì thế, chúng ta phải đi đến một lâu đài của người bảo vệ, một lâu đỉnh cổ đại, một lâu đời nhỏ, nhưng đã trải qua cuộc chiến của người bảo hộ.\nĐột nhiên, một tiếng động mạnh mẽ lên phía trước, chúng tôi phải nhanh chóng bước đi cứu hộ.",
	LEVEL_138_TITLE = "Inner Sanctuary",
	LEVEL_138_HISTORY = "Sau trận chiến khó khăn nhất, chúng tôi cuối cùng đã lấy lại lâu đài của người bảo vệ, và bây giờ chúng tôi có thể vào \"cơ đài thánh\" - nơi là nơi thánh của \"thương tử\" Lunales, chịu trách nhiệm bảo vệ nơi này của Nữ hoàng Thương tử. Đã có thời gian, nhưng mong mọi thứ vẫn còn.",
	LEVEL_139_TITLE = "The Breeding Ground",
	LEVEL_139_HISTORY = "Sự chết của Lunales với sự mất mát của Nữ hoàng, nặng nề đánh bại đạo đức của chúng ta, một bầu không khí mờ mờ giữa các tướng. Từ vua Denas, người ta lại có ý định chiến đấu chống lại kẻ ma quỷ.\nNơi chúng ta đến bây giờ là một lỗ núi lửa khổng lồ, và nguồn gốc của quân đội quái vật.; Đã đến lúc cô đơn ném, cuộc chiến này, chúng ta sẽ trực tiếp đánh con rồng, loại bỏ những điều khó khăn!",
	LEVEL_140_TITLE = "Crown of the Cloud Realm",
	LEVEL_140_HISTORY = "Kết thúc sẽ đến. Các thầy giáo đã nhận ra rằng sự dữ đã đến nơi hy sinh lâu đời. Tian-Sol đang cố gắng lấy được sự tinh tế của máu của các con rồng, trở thành vua của các con hổ không thể tranh luận. Các lực lượng điều tra sẽ xác nhận vị trí chính xác của Tyransol và các binh sĩ của mình, và chúng tôi cũng phải chuẩn bị cho trận chiến cuối cùng.\nLiên minh, đoàn kết! // thời gian đóng cửa của tháp này được cắt giảm từ 25 giây đến 7 giây và không thể được giải quyết bằng cách chi 75 đồng xu.",
	LEVEL_141_TITLE = "Dragon's Gate (Modified)",
	LEVEL_141_HISTORY = "Những nhà thám hiểm bầu trời mang về tin đáng lo ngại: trên vòm trời xa xôi của vương quốc, họ phát hiện một cổng dịch chuyển ma thuật bí ẩn, phủ bụi từ lâu và khắc chữ cổ.\nDù dòng chữ đã cảnh báo rõ ràng: “Không được bước vào vương quốc mây”, nhà vua và Vez’nan vẫn quyết định lên đường để tìm ra sự thật. // Đây là màn 36 của bản mới, có ba lối ra.",
	LEVEL_76_TITLE = "Glacial Rift",
    LEVEL_76_HISTORY = "Đại tướng, chiến tranh chưa kết thúc!\n\nMột tên trộm chạy trốn khỏi vùng đất xung quanh chúng ta và kết hợp với các bộ tộc quỷ khổng lồ còn lại của sông băng để kết hợp với nhau! Cây mồ côi phía bắc cũng đến tìm kiếm một cái lỗ mới trên đất này!\nMạnh mỏi, mờ mờ, nhưng cũng là cơ hội tốt để xây dựng công việc! Các binh sĩ, mang áo mùa đông, rượu vang và vũ khí, vào thung lũng băng - trước khi sức mạnh ác quay trở lại! Bài viết này từ bản KRDove, đây là lời cảm ơn.",
    LEVEL_77_TITLE = "Sleepless Woodland Grave",
    LEVEL_77_HISTORY = "Tướng! Tuy linh hồn của BlakeBon đã biến mất, nhưng linh hồn ác trên trái đất này vẫn chưa được chia rẽ!\n\nỞ trong những cây rừng không ngủ, giới hạn giữa sự chết và sự sống trở nên mờ mịt trong đêm tròn của mỗi tháng, những con lừa dối đang đi bộ giữa những cây kỳ lạ, những nhà sư ác mộng không chết đang xây dựng một cuộc hẹn mới. Nếu không, cả Linirea sẽ bị rơi vào bóng tối!",
	LEVEL_78_HISTORY = "Tướng! Đồng minh của chúng tôi phát hiện ra rằng cỏ rừng mưa gần đây là một người điên rồ! Một số linh hồn rừng đã báo cáo rằng trong rừng có dấu vết của mồ côi phía bắc và mồ cột phía nam! Tôi có thể đoán trước rằng một cuộc hẹn lớn đang phát triển. tướng, chúng ta cần anh và những người lính dũng cảm của anh đi đến rừng để tìm hiểu xem liệu những con thú khủng khiếp này có thể bị tiêu diệt hay không! Bài viết này từ bản KRDove, đây là lời cảm ơn.",
    LEVEL_78_TITLE = "Forest Abyss Spider Lair",
    LEVEL_79_TITLE = "A Night at Storm Atoll",
    LEVEL_79_HISTORY = "Livian đã từ bỏ, nhưng mưa vẫn chưa rút lui! Các linh mục của đền biển đã cảnh báo rằng thảm họa của thảm họa đã trở nên rất yếu trong những ngày gần đây!\n\nBạn cũ của chúng tôi có một tin tức qua quán rượu, hình ảnh của người không chết bắt đầu lặn trong bờ biển bão, ma quỷ sâu thẳm thổi vết thương trong đêm mãi. “Thưa tướng, chúng ta phải thống nhất quân đội và giải tán sự dữ ở đây! Bài viết này từ bản KRDove, đây là lời cảm ơn.",
    LEVEL_80_TITLE = "Skyshaking Ruins",
    LEVEL_80_HISTORY = "Tướng! Tin tức mới nhất cho thấy một lực lượng kỳ lạ đang xoay quanh thung lũng. Các nhà điều tra của chúng tôi báo cáo rằng một người tàn bạo Samantha đang lạm dụng trái đất bằng các thuật ngữ cấm cũ, gây ra sự rối loạn trọng lực không thể giải thích được – đá lớn đang bay lên, bắn súng bị mất kiểm soát, và thậm chí các con dao cũng bắt đầu biến đổi! Họ nói rằng những người Samantha đang sử dụng sức mạnh này để làm thức dậy một con quái vật lâu đời đã ngủ. Nếu họ tiếp tục lễ hội, toàn bộ rừng mưa sẽ bị phá vỡ, rơi xuống, hủy diệt! Đại tướng, xin dẫn dắt quân đội của bạn sâu vào thung lũng, phá vỡ các nghệ thuật ác của họ, để trái đất trở lại trong trật tự bình thường! Chỉ có chế độ chiến đấu, các loại sao có thể được thêm 2 bằng chế độ chiến tranh.",
	LEVEL_86_TITLE = "Lost Gardens",
    LEVEL_86_HISTORY = "Tướng!\n\nVào tháng trọn vẹn cuối cùng, các nhà phù thuật của chúng tôi đã phát hiện ra một sự biến động ma thuật mạnh mẽ. Một ngày sau, một người cảnh sát ở mỏ đá máu báo cáo, sâu trong mỏ đã tìm thấy một khu vườn cổ. Vườn này rất giống với vườn gia đình hoàng gia của chúng tôi, nhưng nó có một hơi thở rác và kỳ lạ. Tôi đã gửi những người lính lính lùn khôn ngoan để khám phá thêm, nhưng không ai quay trở lại.\n\nChị tướng, chúng tôi cần anh và các bạn thân dũng cảm đến khu vườn mất tích này để tìm ra sự thật ở đây! Bài viết này từ bản KRDove, đây là lời cảm ơn.",
	LEVEL_87_TITLE = "Eerie Runes", 
	LEVEL_87_HISTORY = "Đêm tối đế đế đệ đế địch đế đĩ đế đàng đế đài đế đòi đế đạp đế đù đế đà đế đập đế đợt đế được đượng đượt đượp đượn đượi đượu đượm đượa đượo đượ. Từ khi thảm họa nổ ra, sức mạnh của ma thuật tối đã bao quanh vương quốc như một cơn bão, vô số người đã bị nhiễm bệnh, chết, biến thành những người chết trong sự thờ ơ của các tập thể ma quỷ. Tôi theo đuổi một hơi thở ma thuật, sâu vào rừng bị nguyền rủa, và cuối cùng tìm thấy một số hình chữ màu hồng lạ ở gần một dòng sông rừng. Sông tràn đầy khí chết thối màu xanh lá cây, hai bên đều là cây chết và mộ mới. Cả hai bên đều kết nối, chỉ có một cây cầu đá được bao phủ bởi các chữ màu xám cổ. Đây là con đường châm nhập của ma thuật vào vùng đất của vương quốc. Ở đây, một số lực lượng đối phương đang lôi kéo ở đây bị ảnh hưởng bởi dấu hiệu, các đơn vị trước đây đã hoạt động đối với chúng ta cũng biết số lượng bị nhiễm và nổi loạn. Đại tướng, chúng ta phải xây dựng một đường ống phòng ở đây để ngăn chặn những linh hồn bị nhiễm trùng vượt qua cổng qua đường chết này. Bài hát được phát hành từ LPL/RocoKingdom.",
	LEVEL_91_TITLE = "Magic Crystal Altar",
	LEVEL_91_HISTORY = "Tôi tiếp tục theo dõi theo dòng chữ màu hồng, tìm thấy một đền thờ ma thuật ở giữa con sông bị ô nhiễm bởi khí hỏa. Sức mạnh của đền thờ sẽ là đơn vị của chúng tôi có máu quá thấp trước khi bị đánh bại. Xin hãy giữ gìn đường lối sai lầm, phá vỡ sức mạnh này! Bài hát được phát hành từ KPL/RocoKingdom.",
    LEVEL_105_TITLE = "Ravaged Outskirts",
	LEVEL_104_TITLE = "Emerald Treetops",
	LEVEL_123_TITLE = "Darksteel Gates",
