	LEVEL_133_TITLE = "Tempest Island",
	LEVEL_134_TITLE = "The Eye of the Storm",
	LEVEL_135_TITLE = "The Demon King Stronghold",

	LEVEL_150_HISTORY = "Cuối cùng tự do! Không còn gì để chờ đợi, tôi muốn trở lại tháp phòng thủ của tôi?! Tháp bé của tôi là gì?! Đó là cái gì hồn?! Dinar! Chắc chắn là vua hư hỏng này! Tuy nhiên, anh ta không thể lâu.// phiên bản gốc chỉ là mô hình chiến đấu, phiên bản thay thế của mô hình thép anh hùng để đào ra khỏi phiên bản gốc của các vụ phá vỡ.",
	LEVEL_150_TITLE = "Vez'nan's Tower",
	LEVEL_151_HISTORY = "Đẹp lắm! Tháp phòng thủ của tôi cuối cùng trở lại vinh quang của ngày trước. Đã đến lúc ra đi! Các con khỉ này thật sự ngu ngốc, luôn luôn tìm kiếm kho báu nào, nhưng không biết tôi đang chờ đợi chúng ở đây! Đội trưởng. Để chứng minh rằng bạn không phải là một cái rác, hãy nhanh chóng lãnh đạo quân đội của tôi và bắt đầu xâm lược!",
	LEVEL_151_TITLE = "Dwarven Gate",
	LEVEL_152_HISTORY = "Họ nghĩ rằng bằng những cánh cửa yếu đuối này, họ có thể ngăn chặn bước chân của chúng ta? Hạ! Tôi có thể đi qua thành phố cũ này trong vài phút! Đừng lãng phí cơ hội này, không có ý định! Các lực lượng bảo vệ của họ chỉ có một số người nghèo, ngay cả khi bạn có thể dễ dàng giành chiến thắng họ.",
	LEVEL_152_TITLE = "Corridors of the Old City",
	LEVEL_153_HISTORY = "Ồ Ồ! Khu vực khai thác mỏ tuyệt vời. thay vì tôi, chắc chắn sẽ xây dựng tốt hơn ở đây! Họ thực sự đáp ứng được mong muốn của quân đội về vũ khí. Nếu là một người thợ mỏ, thì thật đáng xấu hổ?",
	LEVEL_153_TITLE = "Kazan Mines",
	LEVEL_154_HISTORY = "Khai Hạ! Các nhà điều tra của chúng tôi đã nhúng thuốc kháng sinh vào thức ăn của họ, nhưng những người khổng lồ không biết gì về nó. Họ bây giờ yếu hơn trước đây! Hãy tận dụng cơ hội này để đưa các tướng viên uống một vài thùng rượu, họ bây giờ khô miệng, cần nghỉ ngơi. Làm người lính là vấn đề.",
	LEVEL_154_TITLE = "Golden Brewery",
	LEVEL_155_HISTORY = "Ồ Ồ Ơ Ơ! Làm sao người trong nhà máy luôn cãi nhau và bắn súng! Không thể chịu được! Phải đóng nó! Tôi nghĩ lại một chút. cảm thấy những máy tự động này vẫn rất hữu ích. cho tôi đi lấy nhà máy đó đi. Thậm chí nếu thân thể thép của họ có thể ngăn chặn thanh kiếm của chúng ta, thì họ cũng không thể ngăn chừa phép thuật của chúng ta!",
	LEVEL_155_TITLE = "Clockwork Factory",
	LEVEL_156_HISTORY = "Giữa thánh giá đang ở trước mắt. Xem thêm! Tất cả những kho báu kỳ lạ đều nằm trong một nơi. Để lấy đi dễ dàng hơn! Và ông ấy, ngay ở đó. Boguel, vua người lười biếng, đang ngồi yên trên ngai vàng. Đội trưởng! Hãy xóa nụ cười của anh ta khỏi mặt anh ta, hãy lấy thánh giá!",
	LEVEL_156_TITLE = "Bolgur's Throne",
	LEVEL_157_HISTORY = "Họ có thể học được điều này! Với nguồn lực của họ, mọi người sẽ phải đập nỗi sợ trước mặt quân đội của tôi! Bây giờ chúng ta phải đi lấy một ngàn dặm băng băng bắc. Khí hậu ở đó rất khó khăn, khắp nơi đều là một nhóm người Bắc, nghĩ rằng họ có sức mạnh như vậy. Hãy để họ xem sức mạnh thực sự nằm trong tay ai!",
	LEVEL_157_TITLE = "Northerners' Outpost",
	LEVEL_158_HISTORY = "Nó cũng xứng đáng chiến thắng! Bạn đã cho họ bốc lên, những người Bắc cực khác nghe thấy cảnh báo. nhanh chóng! Khi quân sự nghèo của họ chưa đến, nhanh chóng đi theo dòng chảy lạnh xuống, kiểm soát ngôi làng chủ. Anh tự đánh giá số lượng, đừng làm tôi thất vọng nữa, tướng!",
	LEVEL_158_TITLE = "Frozen Rapids",
	LEVEL_159_HISTORY = "Sống thấy ma! Băng trên dòng chảy đã bị phá vỡ trong trận chiến, khiến cho quân đội bị mất nặng! Tôi phải cho những người Bắc Âu thấy, quân đội của tôi vẫn còn khốn khổ! Nơi làng của chúng ta đã được nắm giữ. Hãy bắt nó, lấy nó, lấy tất cả những gì bạn có thể lấy đi! Họ đã hối tiếc khi bắt đầu đối đầu với chúng tôi!",
	LEVEL_159_TITLE = "Northerners' Village",
	LEVEL_160_HISTORY = "Rác! Bạn đã để cho \"người lãnh đạo Bắc\" đó đi qua con rồng! Ta phải nắm lấy hắn trên núi, giết hắn! Tuyết sắp đến, tôi cảm thấy. Bây giờ hành động! Đừng để bão ngăn cản chúng ta đi. Và những điều xấu xa đó. đừng phá hủy kế hoạch của tôi!",
	LEVEL_160_TITLE = "Dragons' Boneyard",
	LEVEL_161_HISTORY = "Cuối cùng! Đến đỉnh núi. Từ đây tôi có thể thấy Lina. Hạ! Các kẻ ngu ngốc này. chết đến tận cùng vẫn đang kêu! Thật dễ dàng, ông quan chức. “Những gì “Nhà lãnh đạo Bắc” Alcous bị bao quanh như một con rùa! Cơ hội để khắc phục những thiếu sót của bạn nằm trong tay bạn. Hãy lấy nó! Không có sự chuyển đổi của chủ.",
	LEVEL_161_TITLE = "Jokull's Nest",
	LEVEL_162_HISTORY = "Làm đẹp! Đẹp lắm. Bạn có cảm thấy không? Sự bình yên trước khi bão đến? Othel vẫn không biết mình đang phải đối mặt với gì, nhưng chúng tôi biết. Khai thác - ha - ha! Ở đây trại rất thích hợp. Cơ hội thuộc về chúng tôi! Không cần phải bắt được!",
	LEVEL_162_TITLE = "Otil Farmlands",
	LEVEL_163_HISTORY = "Khai thác - ha - ha! Thức ăn dễ dàng từ tay trẻ! Thành phố nhỏ này đã rơi vào tay chúng ta, toàn bộ quân đội đã không vội vàng để chiến thắng một trận chiến nữa. Bây giờ là lượt các con tai mồ hôi! Qua rừng bạc, để những kẻ bắn súng hèn nhát và lãnh đạo của họ, Aleria, gặp gỡ sự khôn ngoan của quân đội tối!",
	LEVEL_163_TITLE = "Silveroak Outpost",
	LEVEL_164_HISTORY = "Như tôi đã đoán, những con quái vật đã chết. Giờ thì Lozagong phải biết ai là chủ nhân thực sự. Chỉ cần lấy thành phố này, chúng ta có thể vượt qua rào cản ma thuật xung quanh Thung lũng Denas. Hãy cẩn thận, tướng. Magnes là một học sinh của tôi trước đây, bây giờ là một người bảo vệ thành phố này. Hãy để người thầy không đi vào nhìn thấy sức mạnh thực sự của phép thuật!",
	LEVEL_164_TITLE = "City of Lozagon",
	LEVEL_165_HISTORY = "Lấy hai! Một cái nữa. mọi thứ gần gũi, tôi đã cảm thấy như thể đã có được hương vị ngọt ngào của chiến thắng. Một người sáng rực rỡ ở phía trước đang chờ đợi anh. nhưng anh ta dường như rất yên tĩnh. anh hùng cũ không thể sống sót này, có coi tôi là một điều hợp lý không? Chụp anh ấy đến gặp tôi! sống được! Hãy để anh ta biết sự thật đằng sau những lời nói dối!",
	LEVEL_165_TITLE = "Lightseeker Camp",
	LEVEL_192_HISTORY = "- Anh có thể đến đây, thật tuyệt, ông tướng! Lời cảnh báo của họ nghe như âm nhạc! Lời nói này là tuyên bố chiến thắng không thể phủ nhận của chúng ta! Hãy đối mặt với thách thức cuối cùng! Quân đội của tôi đã đến cửa lớn của họ, để Dinoz ngu ngốc nhìn thấy ai là người cai trị hợp pháp thực sự! Nếu tôi thắng cuộc chiến cuối cùng, thỏa thuận giữa anh và tôi đã hoàn thành! Mô tả: Để dễ dàng di chuyển, 18 sóng được chia thành 2 cột khác nhau. Đầu tiên chỉ là trận chiến, thứ hai là toàn bộ chiến đấu anh hùng thép.",
	LEVEL_192_TITLE = "Denas's Castle II",
	LEVEL_166_HISTORY = "- Anh có thể đến đây, thật tuyệt, ông tướng! Lời cảnh báo của họ nghe như âm nhạc! Lời nói này là tuyên bố chiến thắng không thể phủ nhận của chúng ta! Hãy đối mặt với thách thức cuối cùng! Quân đội của Ta đã đến tầng hầm của họ, để những kẻ ngu ngốc biết được những người cai trị hợp pháp thật là ai! Hãy tấn công, mở cửa cho họ! Mô tả: Để dễ dàng di chuyển, 18 sóng được chia thành 2 cột khác nhau. Đầu tiên chỉ là trận chiến, thứ hai là toàn bộ chiến đấu anh hùng thép.",
	LEVEL_166_TITLE = "Denas's Castle I",

	LEVEL_167_HISTORY = "Chiến thắng của chúng ta trong những ngày gần đây, dường như khiến mọi người nghĩ rằng họ có khả năng chia một cái giọt. Các người Anurai đã rời khỏi lục địa này và sau đó quay trở lại. Các tinh thể mạnh mẽ mà họ kiểm soát có tầm quan trọng cao đối với kế hoạch tương lai của tôi. Hãy lấy đất này, để họ biết rằng họ không bao giờ xứng đáng sống dưới ánh sáng!",
	LEVEL_167_TITLE = "Maginicia Shores",
	LEVEL_168_HISTORY = "Nhìn xem, tướng! Đội quân của chúng ta đã bị lộ ra, kẻ địch chỉ có bốn phần chạy trốn. Chỉ cần đánh bại quân đội địa phương, đất này là của chúng ta. Hãy cẩn thận, tôi cảm thấy.thiết xuất này hơi sai. Đây là sức mạnh tối tăm mà tôi nhận ra? Nếu tôi không sai, thì phải ngay lập tức ngăn chặn chúng, không thể trì hoãn một phút nào.",
	LEVEL_168_TITLE = "Anurian Plaza",
	LEVEL_169_HISTORY = "Tôi lo lắng điều gì cuối cùng đã xảy ra. Thằng khôn Polyx đã bị phá hủy vì bị lôi cuốn vào việc khám phá bí ẩn cấm. Chẳng lẽ hắn có thể kiểm soát được sức mạnh tối tăm, không có gì gây hại? Khi anh ta không thể ảnh hưởng đến đất này, hãy nhanh chóng đánh bại anh ta và những người bạn của anh ta. Không bao giờ để thất bại!",
	LEVEL_169_TITLE = "Pond of the Sage",

	LEVEL_170_HISTORY = "Câu chuyện về sự tồn tại của Nữ hoàng tuyết cổ xưa là rõ ràng. Bắn súng của chúng ta đã giải phóng cô ấy khỏi tù, và mùa đông vĩnh cửu sẽ lan rộng trên toàn thế giới. Không có lựa chọn. Bạn đã sẵn sàng để gặp gỡ nhân vật trong huyền thoại này?",
	LEVEL_170_TITLE = "Breaking the Ice",
	LEVEL_171_HISTORY = "Nữ hoàng gửi những sinh vật mạnh nhất của bạn đến để rửa bụi cho chúng tôi. Các linh hồn cổ xưa của miền Bắc không có theo đuổi cao hơn, một tâm nghĩ để Rin Winter lan rộng khắp nơi, vui mừng vợ yêu của họ. Họ đã bị hư hỏng trong nhiều thế kỷ. Và tuyết trên núi, lạnh lùng, cũng khiến quân đội chúng ta đau khổ. Hãy cẩn thận, tướng.",
	LEVEL_171_TITLE = "Into the Mountains",
	LEVEL_172_HISTORY = "Cuối cùng! Cuối cùng đến đây! Họ đã tiêu tốn tài nguyên của mình, và chiến binh đói quá. Nữ hoàng Rin Winter đang chờ chúng tôi bắt đầu cuộc chiến cuối cùng. Lại làm việc của cô ấy, chúng tôi sẽ hoàn thành. Sau đó, những gì được ghi trong sách lịch sử sẽ là huyền thoại của chúng ta.",
	LEVEL_172_TITLE = "The Frozen Throne",

	LEVEL_173_HISTORY = "Tôi phải nói rằng các linh mục này thật sự rất bận rộn. Họ đã thoát khỏi mạng thiên đàng của quân đội của chúng tôi, bây giờ đã đến bờ sông, có lẽ họ sẽ gặp gỡ quân sự hỗ trợ được gửi đến bên kia của lâu đài. Tôi không quan tâm đến cái lâu đài trong sa mạc này. Tuy nhiên, chúng ta phải ngăn chặn những người chạy trốn, không bao giờ để họ chạy trốn bằng tàu.",
	LEVEL_173_TITLE = "Ancient Gate",
	LEVEL_174_HISTORY = "Ở đất này, tôi chưa bao giờ thấy những sinh vật như chúng. Có phải là? Không. họ nên thông minh hơn. xin hãy cẩn thận, tướng, tôi thật sự không dám tin rằng quân đội này sẽ là.",
	LEVEL_174_TITLE = "City of Rivers",
	LEVEL_175_HISTORY = "Các linh mục đã làm một điều kỳ lạ. Họ gọi một sinh vật cổ từ một nền văn minh đã bị phá hủy lâu dài, cùng với một bộ răng và một cái vật. Họ nghĩ rằng họ có thể kiểm soát được anh ta. thật ngu ngốc! Họ là những người được kiểm soát – và chúng ta cũng phải bị ảnh hưởng bởi họ! Phải ngăn chặn anh ta với mọi giá, đừng để họ trở lại sức mạnh ban đầu, tướng!",
	LEVEL_175_TITLE = "Dragon's Power",

	LEVEL_176_HISTORY = "Tôi biết rằng phút này cuối cùng sẽ đến. Phù tử của Flad muốn tôi phải trả tiền trước khi họ nợ họ. Giá mà họ mở quá cao! Tôi sẽ không cho họ một nửa sinh vật trên lãnh thổ của tôi! Bây giờ họ đã đến với những sinh vật mạnh nhất của họ, nhưng tôi đã chuẩn bị một số trước đó.",
	LEVEL_176_TITLE = "Back To The Rotten Forest",
	LEVEL_177_HISTORY = "Bây giờ chúng ta phải vào rừng nấm. Đây là nơi nguy hiểm nhất ở Flad, nhưng chúng ta phải đi theo con đường này. Vì khi vượt qua đây, kẻ địch đã tụ tập có thể tấn công quân chúng ta từ phía sau khi quân chúng ta tiến về phía bắc. Hãy cẩn thận với những sinh vật không thể chết mạnh mẽ trong đất liền.",
	LEVEL_177_TITLE = "A Night In The Swamp",
	LEVEL_178_HISTORY = "Cuối cùng đến đây. Đây là cuộc chiến cuối cùng, sau đó bạn sẽ được thoát khỏi mối đe dọa tàn bạo này mãi mãi. Họ sẽ sử dụng tất cả các nguồn lực của mình để tiêu diệt quân đội của chúng tôi. - Thưa ông, ông cũng phải làm như vậy. Các linh hồn cổ đã chết, và năng lượng của họ thật sự quá đầy đủ. Vì vậy, bạn chỉ cần làm suy yếu chúng, sau đó tôi sẽ chịu trách nhiệm đóng chúng.",
	LEVEL_178_TITLE = "The Ancient Ghosts",

	LEVEL_179_HISTORY = "Tôi hiểu rằng họ muốn chịu trách nhiệm về việc đào sâu, đã được lập kế hoạch từ lâu. thông minh, quá thông minh. Như những người này luôn nói, chỉ cần cho họ một in không gian, họ có thể đào ra thế giới dưới lòng đất xa xôi, và sau đó sử dụng nó để chống lại bạn! Giờ là lúc để lại những người lười biếng.",
	LEVEL_179_TITLE = "Excavation Gateway",
	LEVEL_180_HISTORY = "Nó không trông tuyệt vời. Vùng đất dưới lòng đất đang mở rộng nhanh chóng, mọi thứ dường như muốn tiêu thụ mọi thứ xung quanh. Nếu những con khỉ như con khỉ có thể tắm, tôi có thể sẽ cho họ tham gia vào quân đội của tôi, nhưng khủng long sẽ không nói gì. Ở đây chúng ta sẽ ngăn họ tiến lên!",
	LEVEL_180_TITLE = "Lost Passage",
	LEVEL_181_HISTORY = "Họ đào sâu như vậy, thật sự là trò chơi tuyệt vời. nhưng không có gì để sử dụng. Kế hoạch nổi loạn nhỏ này sẽ vẽ những điều sau đây. và những sinh vật đó. chúng ta sẽ cho họ biết tại sao họ lại bị đâm xuống chân, để họ không dám ra khỏi tâm trí tôi nữa!",
	LEVEL_181_TITLE = "The Original World",

	LEVEL_182_HISTORY = "Hải quân của ta đã âm thầm đến bờ biển Hammerhold. Tướng quân, khi pháo hạm bắn hạ tháp địch, hãy đổ bộ và chiếm khu vực. Chuẩn bị thật chu đáo: lần này chúng ta sẽ kết thúc vài huyền thoại.",
	LEVEL_182_TITLE = "Wizard's Landing",
	LEVEL_183_HISTORY = "Tôi không hề hào hứng với bữa tiệc. Họ đang xâm nhập vào nhà của họ, và đó là những gì họ chống lại? - Đừng chờ, đó là một bức tranh nổi tiếng? tướng, hãy cẩn thận, cô ấy thích chơi trò chơi bẩn thỉu, vì vậy hãy cẩn trọng với những ảo tưởng lừa đảo và lừa đảo.",
	LEVEL_183_TITLE = "Sape Oasis",
	LEVEL_184_HISTORY = "Các lực lượng điều tra của chúng tôi chưa trở lại nhiệm vụ của họ. Các người sống sót sợ hãi và mệt mỏi, thổi thổi thở trong kim tự tháp, “một số thứ”. Nếu có sức mạnh trong thung lũng, tôi muốn sở hữu cho bản thân mình, vì vậy bạn nên chuẩn bị cho cuộc điều tra.",
	LEVEL_184_TITLE = "The Lost Empire",
	LEVEL_185_HISTORY = "Cửa của lâu đài Hammer. Tôi phải thừa nhận rằng họ thực sự trông tuyệt vời, nhưng họ không phải là một đối thủ của một quả bóng lửa được đặt đúng cách. Tôi ngạc nhiên khi Marik không đứng với quân đội của mình trên tường thành phố. Hắn dường như đã trở nên hài lòng gần đây. như là Denis không đủ. Thành phố, tướng!",
	LEVEL_185_TITLE = "Hammerhold Streets",
	LEVEL_186_HISTORY = "Thật bất ngờ, Marick đã dám thách thức tôi trong trận đấu tại sân khấu. Một truyền thống cổ đại nói rằng ai thắng thử thách sa mạc thì sẽ trở thành vua của thành phố. Không phải họ có lựa chọn, nhưng như vậy tôi không cần phải đánh bại sự nổi dậy ghét.",
	LEVEL_186_TITLE = "The Grand Arena",

	LEVEL_187_HISTORY = "Các tên cướp biển ghét chúng ta chạy trốn. Lễ hội của họ đi đâu?! Không quan trọng, kẻ địch đi theo tôi mà không vui. Biển là điểm đến tiếp theo của chuyến đi của chúng tôi, tướng. Hãy đưa lá cờ của họ đến với tôi!",
	LEVEL_187_TITLE = "Corsair Brotherhood",
	LEVEL_188_HISTORY = "Một thế hệ cướp biển huyền thoại cuối cùng rơi vào tình trạng này, tôi phải nói tôi rất thất vọng. Bây giờ chúng ta phải chiến đấu với một số con khỉ? Nó là tốt nhất để nói chuyện với họ, để họ biết rằng chúng tôi không đến chơi với những con khỉ!",
	LEVEL_188_TITLE = "Monkey Island",
	LEVEL_189_HISTORY = "Ai sẽ nghĩ rằng con khỉ có thể mang lại cho chúng ta nhiều rắc rối. Ồ, Ồ, con săn tiếp theo của chúng ta là cá sao? Ồ, tôi không thể nhìn thấy một con cá. Đừng yên tâm, tướng. Tôi có thể cảm thấy mình đang bị mắc kẹt từ vài dặm.",
	LEVEL_189_TITLE = "Sharkpool Reef",
	LEVEL_190_HISTORY = "Mùi hôi, mùi hôi của cái chết trong không khí. Đảo này dường như đầy những linh hồn của những tên cướp biển. Lực lượng quân đội có thể thu thêm một số binh sĩ mới. Hãy cho họ biết rằng làm người phục vụ của tôi sau khi chết là nơi tốt nhất để trở về. ☆☆☆☆ ☆☆  ☆ ☆   ☆",
	LEVEL_190_TITLE = "Skullwreck Bay",
	LEVEL_191_HISTORY = "Ồ Ồ! Các kẻ lừa đảo đã thoát khỏi lòng chúng ta, tướng. Không cần lo lắng, nhờ vào làn da chuối bị ném, nó lặn trên nước để tạo ra một con đường vô ý đưa chúng ta đến hòn đảo bí mật của họ. Bây giờ, phải để những kẻ không có trời bướm xuống gối cầu xin lỗi.",
	LEVEL_191_TITLE = "Treasure Island",

	TIP_24 = "Hãy nhớ để nhấp vào kẻ địch, đọc lời khuyên, để biết cách đối phó với họ.",
	TIP_25 = "Thật kỳ diệu khi bị thương đối với kẻ địch.",
	TIP_26 = "Khi các doanh trại được nâng cấp, một nhóm các binh sĩ mới sẽ chạy ra và chiến đấu thay cho những đồng chí mệt mỏi của họ.",
	TIP_27 = "Hãy để một làn sóng của kẻ địch đến sớm, mang lại cho bạn thêm tiền vàng và giảm kỹ năng của thời gian hồi.",
	TIP_28 = "Bạn có thể thay đổi điểm thu thập của doanh trại, để họ di chuyển đến một vị trí thuận lợi để bạn thực hiện chiến lược của riêng bạn.",
	TIP_29 = "Hãy chú ý đến cờ tiếp theo. Nhìn lại, bạn sẽ thấy thông tin về kẻ địch tiếp theo. Chuẩn bị sẵn sàng!",
	TIP_30 = "Hầu hết các đòn đánh có thể gây hại cho kẻ địch bay, ngay cả khi không được nhắm mục tiêu trực tiếp.",
	TIP_31 = "Đôi khi bán tháp phòng thủ hiện không thể sử dụng, có thể cho bạn đủ tiền để vượt qua tình trạng căng thẳng.",
	TIP_32 = "Thường có hiệu quả tốt hơn so với việc xây dựng một tháp phòng thủ nhiều tầng.",
	TIP_33 = "Các kẻ địch không bị ngăn chặn, hầu hết các tháp không bắn vào họ.",
	TIP_34 = "Bạn có thể sử dụng các công cụ mạnh mẽ trong cửa hàng để chiến đấu với bạn. Nó có thể giúp biến toàn bộ chiến tranh!",
	HERO_DOUZHANSHENGFO_CLASS = "Đấu Chiến Thắng Phật",
	HERO_DOUZHANSHENGFO_NAME = "Đấu Chiến Thắng Phật", 
	HERO_DOUZHANSHENGFO_DESCRIPTION = "Sau tám mươi mốt kiếp nạn, Tôn Ngộ Không được phong làm Đấu Chiến Thắng Phật, biểu tượng của trí tuệ và sức mạnh vượt qua gian khó, chiến thắng tà ác.",
	HERO_WUKONG_DESCRIPTION = "Tôn Ngộ Không sinh từ đá tiên hấp thụ linh khí trời đất, mang sức mạnh vô song, tài bay lượn và sự trường sinh. Nay linh châu bị đánh cắp, Đại Thánh lại xuất hành, quyết đoạt lại trước khi quá muộn!",
