	ENEMY_BOSS_DRAGON_STAGE_39_DESCRIPTION = "Con rồng bị tha hóa có máu độc làm ô nhiễm đất đai và nuôi dưỡng đàn rồng con phục vụ chủ nhân Tyransol.",
	ENEMY_BOSS_DRAGON_STAGE_40_DESCRIPTION = "Con ác long đầy tham vọng muốn chiếm đoạt Vân Quốc. Hắn vừa xảo quyệt vừa tàn bạo. Khi hệ số máu của boss vượt 1.1, đòn đánh chuyển sang gây sát thương theo tỷ lệ thay cho mức cố định.",
	ENEMY_BOSS_PIG_DESCRIPTION = "Tự xưng là đỉnh cao của muôn loài, hắn có thể biến thành một con thú khổng lồ.",
	ENEMY_BOSS_CORRUPTED_DENAS_DESCRIPTION = "Vua Linirea bị đánh bại rồi tha hóa bởi sức mạnh hắc ám của Overseer, biến thành một quái vật đáng sợ.",
	ENEMY_BOSS_CULT_LEADER_DESCRIPTION = "Giáo chủ của giáo phái hắc ám, trợ thủ của Overseer. Hắn lập kế hoạch xâm lược những thế giới khác.",
	ENEMY_BOSS_OVERSEER_DESCRIPTION = "Thực thể được gọi là Con Mắt Toàn Tri, xâm nhập các chiều không gian để thôn tính thế giới và hấp thụ năng lượng. Phải ngăn chặn nó bằng mọi giá!",
	ENEMY_BOSS_NAVIRA_DESCRIPTION = "Navira đã nhiễm sức mạnh cấm kỵ và đánh mất ân sủng của nữ thần. Hắn dùng ma thuật chết chóc để khôi phục vinh quang của tộc tinh linh.",
